  2	
  3	/*
  4	 * Địa chỉ ngoại vi từ tài liệu CMSIS-STM32F469XX-H (dòng 1201–1240)
  5	 */
  6	#define PERIPH_BASE           (0x40000000UL)
  7	#define AHB1PERIPH_BASE       (PERIPH_BASE + 0x00020000UL)
  8	
  9	#define RCC_BASE              (AHB1PERIPH_BASE + 0x3800UL)
 10	#define RCC_AHB1ENR           (*(volatile uint32_t *)(RCC_BASE + 0x30UL))
 11	
 12	#define GPIOA_BASE            (AHB1PERIPH_BASE + 0x0000UL)
 13	#define GPIOD_BASE            (AHB1PERIPH_BASE + 0x0C00UL)
 14	#define GPIOG_BASE            (AHB1PERIPH_BASE + 0x1800UL)
 15	#define GPIOK_BASE            (AHB1PERIPH_BASE + 0x2800UL)
 16	
 17	/* Các thanh ghi GPIO cần dùng */
 18	#define GPIOA_MODER           (*(volatile uint32_t *)(GPIOA_BASE + 0x00UL))
 19	#define GPIOA_PUPDR           (*(volatile uint32_t *)(GPIOA_BASE + 0x0CUL))
 20	#define GPIOA_IDR             (*(volatile uint32_t *)(GPIOA_BASE + 0x10UL))
 21	
 22	#define GPIOD_MODER           (*(volatile uint32_t *)(GPIOD_BASE + 0x00UL))
 23	#define GPIOD_BSRR            (*(volatile uint32_t *)(GPIOD_BASE + 0x18UL))
 24	
 25	#define GPIOG_MODER           (*(volatile uint32_t *)(GPIOG_BASE + 0x00UL))
 26	#define GPIOG_BSRR            (*(volatile uint32_t *)(GPIOG_BASE + 0x18UL))
 27	
 28	#define GPIOK_MODER           (*(volatile uint32_t *)(GPIOK_BASE + 0x00UL))
 29	#define GPIOK_BSRR            (*(volatile uint32_t *)(GPIOK_BASE + 0x18UL))
 30	
 31	/*
 32	 * Bit kích hoạt xung nhịp RCC AHB1 từ CMSIS-STM32F469XX-H (dòng 14001–14040)
 33	 */
 34	#define RCC_AHB1ENR_GPIOAEN   (1UL << 0)
 35	#define RCC_AHB1ENR_GPIODEN   (1UL << 3)
 36	#define RCC_AHB1ENR_GPIOGEN   (1UL << 6)
 37	#define RCC_AHB1ENR_GPIOKEN   (1UL << 10)
 38	
 39	/*
 40	 * Thông số chân 4 đèn LED & Nút bấm từ Fact dự án:
 41	 * - LED1 (Green):  PG6  (Fact f-8008940bff, BSP-STM32469I-DISCO-H dòng 121–160)
 42	 * - LED2 (Orange): PD4  (Fact f-76c09827fe, BSP-STM32469I-DISCO-H dòng 121–160)
 43	 * - LED3 (Red):    PD5  (Fact f-1357924537, BSP-STM32469I-DISCO-H dòng 121–160)
 44	 * - LED4 (Blue):   PK3  (Fact f-61ed792479, BSP-STM32469I-DISCO-H dòng 121–160)
 45	 * - USER_BUTTON:   PA0  (Fact f-e3204af421, f-0a0ea12b9e, BSP-STM32469I-DISCO-H dòng 161–200)
 46	 *
 47	 * Mức tích cực theo BSP-STM32469I-DISCO-C:
 48	 * - LED: Active LOW (Fact f-2853301d9b bật = GPIO_PIN_RESET, Fact f-805562b793 tắt = GPIO_PIN_SET)
 49	 * - Nút USER: Active HIGH (Fact f-be0a482f3c sườn lên GPIO_MODE_IT_RISING, bấm = 1, nhả = 0)
 50	 */
 51	#define LED1_PIN              (6U)  /* PG6 */
 52	#define LED2_PIN              (4U)  /* PD4 */
 53	#define LED3_PIN              (5U)  /* PD5 */
 54	#define LED4_PIN              (3U)  /* PK3 */
 55	
 56	#define BUTTON_PIN            (0U)  /* PA0 */
 57	
 58	static void led_set(uint8_t led_index, uint8_t on) {
 59	    /* on = 1 -> kéo xuống 0 (BSRR bit 16..31)
 60	     * on = 0 -> kéo lên 1 (BSRR bit 0..15)
 61	     */
 62	    switch (led_index) {
 63	        case 1: /* LED1: PG6 */
 64	            GPIOG_BSRR = on ? (1UL << (LED1_PIN + 16)) : (1UL << LED1_PIN);
 65	            break;
 66	        case 2: /* LED2: PD4 */
 67	            GPIOD_BSRR = on ? (1UL << (LED2_PIN + 16)) : (1UL << LED2_PIN);
 68	            break;
 69	        case 3: /* LED3: PD5 */
 70	            GPIOD_BSRR = on ? (1UL << (LED3_PIN + 16)) : (1UL << LED3_PIN);
 71	            break;
 72	        case 4: /* LED4: PK3 */
 73	            GPIOK_BSRR = on ? (1UL << (LED4_PIN + 16)) : (1UL << LED4_PIN);
 74	            break;
 75	        default:
 76	            break;
 77	    }
 78	}
 79	
 80	static void all_leds(uint8_t on) {
 81	    led_set(1, on);
 82	    led_set(2, on);
 83	    led_set(3, on);
 84	    led_set(4, on);
 85	}
 86	
 87	static uint8_t button_is_pressed(void) {
 88	    /* PA0 đọc mức 1 là đang bấm (Active HIGH) */
 89	    return (GPIOA_IDR & (1UL << BUTTON_PIN)) ? 1U : 0U;
 90	}
 91	
 92	static void delay_cycles(volatile uint32_t count) {
 93	    while (count--) {
 94	        __asm__ volatile ("nop");
 95	    }
 96	}
 97	
 98	int main(void) {
 99	    /* 1. Bật xung nhịp cho các cổng GPIOA, GPIOD, GPIOG, GPIOK */
100	    RCC_AHB1ENR |= (RCC_AHB1ENR_GPIOAEN | RCC_AHB1ENR_GPIODEN |
101	                    RCC_AHB1ENR_GPIOGEN | RCC_AHB1ENR_GPIOKEN);
102	
103	    /* 2. Cấu hình các chân LED thành General Purpose Output mode (01b) */
104	    /* PG6 (LED1) */
105	    GPIOG_MODER &= ~(3UL << (LED1_PIN * 2));
106	    GPIOG_MODER |=  (1UL << (LED1_PIN * 2));
107	
108	    /* PD4 (LED2), PD5 (LED3) */
109	    GPIOD_MODER &= ~((3UL << (LED2_PIN * 2)) | (3UL << (LED3_PIN * 2)));
110	    GPIOD_MODER |=  ((1UL << (LED2_PIN * 2)) | (1UL << (LED3_PIN * 2)));
111	
112	    /* PK3 (LED4) */
113	    GPIOK_MODER &= ~(3UL << (LED4_PIN * 2));
114	    GPIOK_MODER |=  (1UL << (LED4_PIN * 2));
115	
116	    /* 3. Cấu hình chân PA0 (USER BUTTON) thành Input mode (00b) */
117	    GPIOA_MODER &= ~(3UL << (BUTTON_PIN * 2));
118	    /* Theo BSP dòng 281-320: Pull = GPIO_NOPULL (00b) */
119	    GPIOA_PUPDR &= ~(3UL << (BUTTON_PIN * 2));
120

121	    /* Ban đầu tắt tất cả các đèn LED */
122	    all_leds(0);
123	
124	    uint8_t step = 1;
125	
126	    while (1) {
127	        if (button_is_pressed()) {
128	            /*
129	             * CHẾ ĐỘ 2: Nút đang BẤM
130	             * Phản ứng đổi rõ rệt: Cả 4 đèn LED chớp nháy đồng loạt cực nhanh (khác hẳn chạy tuần tự)
131	             */
132	            all_leds(1);
133	            delay_cycles(200000);
134	            all_leds(0);
135	            delay_cycles(200000);
136	        } else {
137	            /*
138	             * CHẾ ĐỘ 1: Nút đang NHẢ (bình thường)
139	             * Chạy tuần tự vòng quanh 4 đèn (Green -> Orange -> Red -> Blue)
140	             */
141	            led_set(1, (step == 1));
142	            led_set(2, (step == 2));
143	            led_set(3, (step == 3));
144	            led_set(4, (step == 4));
145	
146	            delay_cycles(400000);
147	
148	            step++;
149	            if (step > 4) {
150	                step = 1;
151	            }
152	        }
153	    }
154	
155	    return 0;
156	}

